    }

    private fun declaredDeepLinkUri(): String? {
        val launch = given.optJSONObject("launch")
        return launch?.firstString("uri", "url", "article") ?: given.firstString("uri", "deepLinkUri")
    }

    companion object {
        const val PREFS = EvergreenAccountRepository.PREFS_NAME
        const val REGISTRATION_REQUEST_CODE = 4207

        const val SURFACE_MAIN = "main"
        const val SURFACE_ARTICLE = "article"
