        const val ENTRY_POINT_ORDINARY = "ordinary"
        const val ENTRY_POINT_EXTERNAL_ARTICLE = "external_article_deep_link"

        const val EFFECT_IMPRESSION_RECORDED = "recordAccountEncouragementImpression"
        const val EFFECT_ENCOURAGEMENT_PRESENTED = "presentAccountEncouragement"
        const val EFFECT_DEFERRED = "deferAccountEncouragement"
        const val EFFECT_DISMISSED_PERMANENTLY = "dismissAccountEncouragementPermanently"
        const val EFFECT_REGISTRATION_REQUESTED = "requestAccountCreation"
        const val EFFECT_REGISTRATION_UNAVAILABLE = "registrationFlowUnavailable"
        const val EFFECT_REGISTRATION_NOT_COMPLETED = "registrationNotCompleted"
        const val EFFECT_ACCOUNT_CREATED = "accountCreated"
        const val EFFECT_EXTERNAL_ARTICLE_LOADED = "loadRequestedExternalArticle"
