{"content":"package org.wikipedia.evergreen

import android.app.Activity
import android.content.Context
import android.content.Intent
import org.json.JSONArray
import org.json.JSONObject
import org.wikipedia.evergreen.auth.RegistrationFlow
import org.wikipedia.evergreen.auth.RegistrationOutcome
import org.wikipedia.evergreen.data.AccountStateRepository
import org.wikipedia.evergreen.data.EvergreenAccountRepository
import org.wikipedia.evergreen.data.LaunchPromptStateRepository
import org.wikipedia.evergreen.data.ReadingHistoryStore
import org.wikipedia.evergreen.data.SavedPagesStore
import org.wikipedia.evergreen.encouragement.AccountEncouragementEligibility
import org.wikipedia.evergreen.encouragement.LaunchPromptCoordinator
import org.wikipedia.evergreen.encouragement.LaunchPromptCoordinator.LaunchRequest
import org.wikipedia.evergreen.encouragement.ReadingEngagementSummary
import org.wikipedia.evergreen.platform.AppClock
import org.wikipedia.evergreen.platform.MethodTrace
import org.wikipedia.evergreen.runtime.ArticleDeepLink
import org.wikipedia.evergreen.runtime.RuntimeEventIntent
import org.wikipedia.evergreen.runtime.RuntimeGivenAdapter

/**
 * Page owner for the account creation encouragement.
 *
 * It owns the visible surface, the launch decision and the answer to it: presenting the screen
 * and recording exactly one impression for it, deferring with **Maybe later**, opting out for
 * good with the close control, and handing off to the registration first authentication flow.
 *
 * All state lives in application owned stores, so every one of those outcomes survives activity
 * and process recreation.
 */
class EvergreenPageOwner(private val context: Context) {

    private val clock = AppClock()
    private val trace = MethodTrace()
    private val effects = JSONArray()

    private val history = ReadingHistoryStore(context)
    private val accounts = AccountStateRepository(context)
    private val evergreen = EvergreenAccountRepository(context, clock)
    private val savedPages = SavedPagesStore(context)
    private val launchPrompts = LaunchPromptStateRepository(context)
    private val engagement = ReadingEngagementSummary(history, savedPages, clock)
    private val eligibility = AccountEncouragementEligibility(history, evergreen, accounts, clock, trace)
    private val coordinator = LaunchPromptCoordinator(launchPrompts, eligibility, trace)
    private val registration = RegistrationFlow(accounts)
    private val fixture = RuntimeGivenAdapter(
        clock = clock,
        accounts = accounts,
        evergreen = evergreen,
        history = history,
        savedPages = savedPages,
        launchPrompts = launchPrompts,
    )

    private val given = JSONObject()
    private var launchRequest: LaunchRequest = LaunchRequest.Ordinary
    private var state = JSONObject()
        .put("surface", SURFACE_MAIN)
        .put("accountEncouragementVisible", false)
    private var decision = JSONObject()
        .put("evaluated", false)
        .put("shouldShow", false)
        .put("reason", "")

    /** Establishes the application owned stores for this launch and restores the screen. */
    fun mount(input: JSONObject) {
        trace.record("mount")
        input.keys().forEach { key -> given.put(key, input.get(key)) }
        fixture.apply(given)
        launchRequest = launchRequestFrom(given)
        restoreScreen()
    }

    fun dispatch(event: JSONObject) {
        trace.record(event.optString("name"))
        val intent = RuntimeEventIntent.parse(event)
        apply(intent)
        if (intent.relaunchAfterwards) {
            trace.record("pageOwner.relaunchApplication")
            val relaunch = if (intent.kind == RuntimeEventIntent.Kind.EXTERNAL_DEEP_LINK) {
                launchRequest
            } else {
                LaunchRequest.Ordinary
            }
            onLaunchRequested(relaunch)
        }
    }

    /** Production answer to "would an ordinary launch show the encouragement right now?". */
    fun ordinaryLaunchWouldShow(): Boolean {
        trace.record("ordinaryLaunchWouldShow")
        return coordinator.evaluate(LaunchRequest.Ordinary).shouldShow
    }

    /** An ordinary application launch or resume. */
    fun onLaunchRequested(request: LaunchRequest) {
        launchRequest = request
        val outcome = coordinator.evaluate(request)
        decision = JSONObject()
            .put("evaluated", outcome.evaluated)
            .put("shouldShow", outcome.shouldShow)
            .put("reason", outcome.reason)

        if (request is LaunchRequest.ExternalArticle) {
            routeExternalArticle(request.uri)
            return
        }
        if (restorePendingEncouragement()) {
            return
        }
        if (outcome.shouldShow) {
            presentEncouragement(recordImpression = true)
        } else {
            showMainSurface()
        }
    }

    /** Launched straight into an external article link. */
    fun onExternalArticleLaunched(uri: String) {
        trace.record("pageOwner.onExternalArticleLaunched")
        onLaunchRequested(LaunchRequest.ExternalArticle(uri))
    }

    /** **Maybe later**: closes the screen without permanently opting out. */
    fun onMaybeLaterSelected() {
        trace.record("pageOwner.onMaybeLaterSelected")
        evergreen.clearPendingEncouragement()
        effects.put(
            JSONObject()
                .put("name", EFFECT_DEFERRED)
                .put("impressions", evergreen.impressionCount())
                .put("lastImpressionDate", evergreen.lastImpressionDate())
                .put("permanentlyDismissed", evergreen.isPermanentlyDismissed())
        )
        showMainSurface()
    }

    /** The screen's close control: a permanent opt out that survives later launches. */
    fun onCloseSelected() {
        trace.record("pageOwner.onCloseSelected")
        evergreen.dismissPermanently(clock.today())
        effects.put(
            JSONObject()
                .put("name", EFFECT_DISMISSED_PERMANENTLY)
                .put("dismissedOn", evergreen.permanentDismissalDate())
                .put("impressions", evergreen.impressionCount())
                .put("lastImpressionDate", evergreen.lastImpressionDate())
        )
        showMainSurface()
    }

    /** **Create account**: opens the registration first authentication flow. */
    fun onCreateAccountSelected() {
        if (!encouragementVisible()) {
            trace.record("pageOwner.onCreateAccountSelectedUnavailable")
            return
        }
        trace.record("pageOwner.onCreateAccountSelected")
        trace.record("registrationFlow.buildRegistrationIntent")
        val intent = registration.buildRegistrationIntent()
        effects.put(
            JSONObject()
                .put("name", EFFECT_REGISTRATION_REQUESTED)
                .put("flow", RegistrationFlow.FLOW_REGISTRATION_FIRST)
                .put("externalPackage", RegistrationFlow.EXTERNAL_AUTHENTICATION_PACKAGE)
                .put("externalUri", RegistrationFlow.REGISTRATION_URI)
        )
        if (launchExternal(intent)) {
            return
        }
        effects.put(JSONObject().put("name", EFFECT_REGISTRATION_UNAVAILABLE))
        keepEncouragementVisible()
    }

    /** Result of the authentication leaf, as reported by the harness. */
    fun onRegistrationLeafResult(leafResult: String?) {
        trace.record("registrationFlow.mapLeafResult")
        applyRegistrationOutcome(registration.mapLeafResult(leafResult))
    }

    /** Result of the authentication leaf, as delivered by the activity result channel. */
    fun onRegistrationActivityResult(resultCode: Int, data: Intent?) {
        trace.record("registrationFlow.mapActivityResult")
        applyRegistrationOutcome(registration.mapActivityResult(resultCode, data))
    }

    fun snapshot(): JSONObject {
        val entryPoint = if (launchRequest is LaunchRequest.ExternalArticle) {
            ENTRY_POINT_EXTERNAL_ARTICLE
        } else {
            ENTRY_POINT_ORDINARY
        }
        val externalUri = (launchRequest as? LaunchRequest.ExternalArticle)?.uri.orEmpty()
        return JSONObject()
            .put("featureAvailable", true)
            .put("decision", JSONObject(decision.toString()))
            .put("state", JSONObject(state.toString()))
            .put(
                "persistence",
                JSONObject()
                    .put("impressions", evergreen.impressionCount())
                    .put("lastImpressionDate", evergreen.lastImpressionDate())
                    .put("permanentlyDismissed", evergreen.isPermanentlyDismissed())
                    .put("permanentDismissalDate", evergreen.permanentDismissalDate())
                    .put("pendingEncouragement", evergreen.isEncouragementPending())
            )
            .put(
                "account",
                JSONObject()
                    .put("kind", accounts.registrationKind().storageValue)
                    .put("isPermanent", accounts.isPermanentAccount())
            )
            .put(
                "launch",
                JSONObject()
                    .put("entryPoint", entryPoint)
                    .put("uri", externalUri)
            )
            .put("effects", JSONArray(effects.toString()))
            .put("invokedProductionMethods", trace.toJsonArray())
    }

    /** Releases the resources this page owner holds. */
    fun release() {
        history.close()
    }

    private fun apply(intent: RuntimeEventIntent) {
        when (intent.kind) {
            RuntimeEventIntent.Kind.ORDINARY_LAUNCH ->
                onLaunchRequested(LaunchRequest.Ordinary)
            RuntimeEventIntent.Kind.EXTERNAL_DEEP_LINK ->
                onLaunchRequested(
                    LaunchRequest.ExternalArticle(intent.uri ?: declaredDeepLinkUri().orEmpty())
                )
            RuntimeEventIntent.Kind.MAYBE_LATER ->
                onMaybeLaterSelected()
            RuntimeEventIntent.Kind.PERMANENT_CLOSE ->
                onCloseSelected()
            RuntimeEventIntent.Kind.CREATE_ACCOUNT ->
                onCreateAccountSelected()
            RuntimeEventIntent.Kind.CREATE_ACCOUNT_THEN_OUTCOME -> {
                onCreateAccountSelected()
                onRegistrationLeafResult(intent.leafResult)
            }
            RuntimeEventIntent.Kind.REGISTRATION_OUTCOME ->
                onRegistrationLeafResult(intent.leafResult)
        }
    }

