                    .put("name", EFFECT_IMPRESSION_RECORDED)
                    .put("impressions", evergreen.impressionCount())
                    .put("date", evergreen.lastImpressionDate())
            )
        }
        evergreen.markEncouragementPending()
        trace.record("pageOwner.presentAccountEncouragement")
        effects.put(
            JSONObject()
                .put("name", EFFECT_ENCOURAGEMENT_PRESENTED)
                .put("impressions", evergreen.impressionCount())
                .put("lastImpressionDate", evergreen.lastImpressionDate())
        )
        val counts = engagement.current()
        state = JSONObject()
            .put("surface", SURFACE_ENCOURAGEMENT)
            .put("accountEncouragementVisible", true)
            .put("encouragementMessage", counts.describe())
            .put("readingCount", counts.articlesRead)
            .put("savedCount", counts.pagesSaved)
            .put("recentUseCount", counts.recentlyUsedPages)
    }

    private fun keepEncouragementVisible() {
        if (evergreen.isEncouragementPending()) {
