package org.wikipedia.evergreen

import android.app.Activity
import android.content.Intent
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.Button
import android.widget.LinearLayout
import android.widget.TextView
import org.json.JSONObject

/**
 * Production entry point.
 *
 * It hosts [EvergreenPageOwner] and renders whatever surface the page owner owns: the reader's
 * ordinary surface, an article requested by an external deep link, or the account creation
 * encouragement with its **Create account**, **Maybe later** and close controls.
 */
class BenchmarkActivity : Activity() {

    lateinit var pageOwner: EvergreenPageOwner
        private set

    private lateinit var status: TextView
    private lateinit var articleView: TextView
    private lateinit var encouragementPanel: LinearLayout
    private lateinit var encouragementCounts: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        pageOwner = EvergreenPageOwner(this)
        pageOwner.mount(JSONObject(intent.getStringExtra(EXTRA_RUNTIME_GIVEN).orEmpty()))

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.START
            setPadding(32, 32, 32, 32)
        }
        root.addView(TextView(this).apply { text = "Wikipedia"; textSize = 30f })
        status = TextView(this).apply { textSize = 22f }
        root.addView(status)
        articleView = TextView(this).apply { textSize = 18f; visibility = View.GONE }
        root.addView(articleView)
        encouragementPanel = buildEncouragementPanel()
        root.addView(encouragementPanel)
        setContentView(root)

        val deepLink = if (intent.action == Intent.ACTION_VIEW) intent.data?.toString() else null
        if (!deepLink.isNullOrEmpty()) {
            pageOwner.onExternalArticleLaunched(deepLink)
        }
        render()
    }

    fun dispatch(event: JSONObject) {
        pageOwner.dispatch(event)
        render()
    }

    fun ordinaryLaunchWouldShow(): Boolean = pageOwner.ordinaryLaunchWouldShow()

    fun snapshot(): JSONObject = pageOwner.snapshot()

    @Suppress("DEPRECATION")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == EvergreenPageOwner.REGISTRATION_REQUEST_CODE) {
            pageOwner.onRegistrationActivityResult(resultCode, data)
            render()
        }
    }

    override fun onDestroy() {
        pageOwner.release()
        super.onDestroy()
    }

    private fun buildEncouragementPanel(): LinearLayout {
        val panel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.START
            visibility = View.GONE
        }
        panel.addView(TextView(this).apply { text = "Create an account"; textSize = 24f })

        val counts = TextView(this).apply { textSize = 18f }
        panel.addView(counts)
        encouragementCounts = counts

        panel.addView(Button(this).apply {
            text = "Create account"
            contentDescription = "Create account"
            setOnClickListener {
                pageOwner.onCreateAccountSelected()
                render()
            }
        })
        panel.addView(Button(this).apply {
            text = "Maybe later"
            contentDescription = "Maybe later"
            setOnClickListener {
                pageOwner.onMaybeLaterSelected()
                render()
            }
        })
